        return edges[(v, u)]

    # Degree constraints (min 3, max 7)
    for i in range(n):
        incident = []
        for j in range(n):
            if i != j:
                incident.append(get_edge(i, j))

        cnf1 = CardEnc.atleast(lits=incident, bound=3, top_id=var_idx)
        for clause in cnf1.clauses:
            solver.add_clause(clause)
        var_idx = max([var_idx] + [abs(l) for c in cnf1.clauses for l in c]) + 1

        cnf2 = CardEnc.atmost(lits=incident, bound=7, top_id=var_idx)
        for clause in cnf2.clauses:
            solver.add_clause(clause)
        var_idx = max([var_idx] + [abs(l) for c in cnf2.clauses for l in c]) + 1

    # Girth at least 7 means no cycles of length 3, 4, 5, 6
    # Cycle of length 3
    for i, j, k in itertools.combinations(range(n), 3):
        solver.add_clause([-get_edge(i, j), -get_edge(j, k), -get_edge(i, k)])

    # Cycle of length 4
    for i, j, k, l in itertools.combinations(range(n), 4):
        solver.add_clause([-get_edge(i, j), -get_edge(j, k), -get_edge(k, l), -get_edge(i, l)])
        solver.add_clause([-get_edge(i, j), -get_edge(j, l), -get_edge(l, k), -get_edge(i, k)])
        solver.add_clause([-get_edge(i, k), -get_edge(k, j), -get_edge(j, l), -get_edge(i, l)])

    # Cycle of length 5
    for c in itertools.combinations(range(n), 5):
        for p in [[0,1,2,3,4], [0,1,2,4,3], [0,1,3,2,4], [0,1,3,4,2], [0,1,4,2,3], [0,1,4,3,2],
                  [0,2,1,3,4], [0,2,1,4,3], [0,2,3,1,4], [0,2,4,1,3], [0,3,1,2,4], [0,3,2,1,4]]:
            v = [c[x] for x in p]
            solver.add_clause([-get_edge(v[0], v[1]), -get_edge(v[1], v[2]), -get_edge(v[2], v[3]), -get_edge(v[3], v[4]), -get_edge(v[4], v[0])])

    # Cycle of length 6
    for c in itertools.combinations(range(n), 6):
        perms = itertools.permutations(c[1:])
        for p in perms:
            if p[0] < p[-1]:
                v = (c[0],) + p
                solver.add_clause([-get_edge(v[0], v[1]), -get_edge(v[1], v[2]), -get_edge(v[2], v[3]), -get_edge(v[3], v[4]), -get_edge(v[4], v[5]), -get_edge(v[5], v[0])])

    print("Constraints added, solving...")
    res = solver.solve()
    print("SATISFIABLE:", res)
    if res:
        model = solver.get_model()
        ans = []
        for i in range(n):
            for j in range(i+1, n):
                if model[edges[(i, j)] - 1] > 0:
                    ans.append([i, j])
        print("SOLUTION:", ans)

